//! `shadows`: the Ep1 shadow creatures. One shared C source (`Monster_Base.c`, `Shadows_base.c`,
//! `Shadows_Base_Particle.c`, `ShadowsEpisodeOne.c`) compiled with a per-level file
//! (`ShadowsLevel<N>.c`) into one module per level pack.
//! Port of `Game Logic Modules/Ep1_Library/Characters/SHADOWS/..`. Reference build: shadowslevelone.
//! The 4 builds are listed in `tools/rustport/shadows_family.txt`; per-build literals and code shapes
//! are in [`builds`] (generated by tools/rustport/gen_builds.py), the initialised tables in [`maps`].
//!
//! This is a monster side of the Tome of Doom: a shadow waits at its post, sneaks up on the leader
//! hero and attacks; while the book is open it goes back to its post (`TomeIsOpen` event 0x200 ->
//! `Shadows_BaseTR_RETURN_TO_STARTING_POSITION`, state 0x17 FLEE_TOME) and keeps away
//! (0x18 STAY_AWAY_FROM_TOME, "bouga" scare attacks); hooked by the beam (0xd6/0x65 -> event 0x40 ->
//! `Shadows_BaseTR_EVENT_SHADOWS_IS_HOOKED_BEINGSUCKED`, state 0x14) it struggles and lashes out, and
//! is pulled in (0xd6/0x67) and captured (0xd6/0x68 -> `Monster_BaseST_CAPTURED`).
//!
//! Module globals are shared by every instance (the engine swaps `pLocalData*` per instance), as on
//! the PS2. `pLocalDataMonster_Base` and `pLocalDataShadows_Base` both point at the instance's one
//! local data block (GetLocalData grows and shares it), likewise the two global data pointers.
#![allow(non_snake_case, non_upper_case_globals, unused_variables, unused_mut, unused_assignments)]
#![allow(clippy::all)]

pub mod builds;
pub mod maps;

mod level;
mod monster_base;
mod shadows_base;
mod shadows_base_particle;

pub use level::*;
pub use monster_base::*;
pub use shadows_base::*;
pub use shadows_base_particle::*;

use crate::engine::{Engine, Mem, Ptr};
use crate::logic::{LResult, ModuleDef};

pub static MODULE: ModuleDef = ModuleDef {
    name: "shadows",
    data_size: DATA_SIZE,
    ctor: shadows_levelConstructor,
    dtor: shadows_levelDestructor,
    register: None,
    // the initialised data the code reads (goCustomDataShadows, TmpMonsterMap) is written per build
    // by shadows_build_init; string literals are interned with `e.cstr`.
    init: &[],
    build_init: Some(shadows_build_init),
};

/// Index of a build in [`builds::BUILDS`] by its directory name.
pub fn build_index(sha8: &str) -> Option<usize> {
    builds::BUILDS.iter().position(|b| b.sha8 == sha8)
}

fn shadows_build_init(m: &mut Mem, data: Ptr, build: usize) {
    for (i, &w) in maps::GO_CUSTOM_DATA_SHADOWS[build].iter().enumerate() {
        m.w32(data + (goCustomDataShadows - 0x10000) + i as u32 * 4, w);
    }
    for (i, &w) in maps::TMP_MONSTER_MAP[build].iter().enumerate() {
        m.w32(data + (TmpMonsterMap - 0x10000) + i as u32 * 4, w);
    }
}

// ---- module globals ----
// The builds place their globals at different addresses (the two tables have per-level sizes); the
// image is private to the module, so the port uses one layout for every build: the tables at their
// largest size, then the pointers in _globals.h order.
/// per-shadow data: records {object id, sector mask (L+0x180), kill mask (L+0x40)} of 0xc bytes;
/// 72 bytes max
pub const goCustomDataShadows: u32 = 0x10000;
/// per-monster-type data: records of 0x3c bytes {type, speeds and ranges...}; 240 bytes max
pub const TmpMonsterMap: u32 = 0x10048;
pub const pAnimMngr: u32 = 0x10138;
pub const pFunction: u32 = 0x1013c;
pub const pMiscFunc: u32 = 0x10140;
pub const pDebug: u32 = 0x10144;
pub const pExtra: u32 = 0x10148;
pub const pGameObj: u32 = 0x1014c;
pub const pPhysic: u32 = 0x10150;
pub const pAnim: u32 = 0x10154;
pub const pStdlib: u32 = 0x10158;
pub const pSound: u32 = 0x1015c;
pub const pParticle: u32 = 0x10160;
pub const pLocalDataShadows_Base: u32 = 0x10164;
pub const pGlobalDataShadows_Base: u32 = 0x10168;
/// never used by the code
pub const uiToStatusPointerMap: u32 = 0x1016c;
pub const pLocalDataMonster_Base: u32 = 0x10174;
pub const pGlobalDataMonster_Base: u32 = 0x10178;
pub const pGraphic: u32 = 0x1017c;
pub const DATA_SIZE: u32 = 0x180;

/// `ALL` joint / bone selector (0x7fffffff)
pub(crate) const ALL: u32 = 0x7fff_ffff;

/// Address of a module global.
#[inline]
pub(crate) fn G(e: &Engine, a: u32) -> Ptr {
    e.rt.cur_data() + (a - 0x10000)
}
/// Current value of `pLocalDataShadows_Base` (this instance's local data).
#[inline]
pub(crate) fn L(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDataShadows_Base))
}
/// Current value of `pLocalDataMonster_Base` (the same block as [`L`] once both are registered).
#[inline]
pub(crate) fn LM(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDataMonster_Base))
}
/// Current value of `pGlobalDataMonster_Base` (byte-addressed: [0] game buffer 0, [1] game buffer 2,
/// [2] game buffer 1, [3] the APIcons table, set by shadows_baseConstructor).
#[inline]
pub(crate) fn GDM(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDataMonster_Base))
}
/// Current value of `pGlobalDataShadows_Base` (the same block as [`GDM`]).
#[inline]
pub(crate) fn GDS(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDataShadows_Base))
}
/// Per-build literal (see builds.rs).
#[inline]
pub(crate) fn k(e: &Engine, i: usize) -> u32 {
    builds::BUILDS[e.rt.cur_build()].k[i]
}
/// Per-build code shape group of a function (see builds.rs).
#[inline]
pub(crate) fn g(e: &Engine, i: usize) -> u8 {
    builds::BUILDS[e.rt.cur_build()].g[i]
}
/// The current build's directory name.
#[inline]
pub(crate) fn build_key(e: &Engine) -> &'static str {
    builds::BUILDS[e.rt.cur_build()].sha8
}

/// `pcVar = (*((APIcons *)pGlobalDataShadows_Base[3])->GetExternalFunction)(idx); (*pcVar)(0);`
/// Runs the module function registered under `idx` at once, inside the current logic call (no
/// setjmp of its own: a ChangeState/Break in it unwinds the caller as well, as on the PS2). A NULL
/// entry is a call through NULL in the original: panic.
pub(crate) fn call_external_now(e: &mut Engine, idx: u32) -> LResult<()> {
    let c = e.rt.current_code().expect("GetExternalFunction outside of a logic call");
    let f = e
        .GetFunction(c, idx)
        .unwrap_or_else(|| panic!("shadows: call through NULL (external function {idx:#x} not set)"));
    f(e, 0)?;
    Ok(())
}

/// `*a |= bits`
#[inline]
pub(crate) fn or32(e: &mut Engine, a: Ptr, bits: u32) {
    let v = e.r32(a);
    e.w32(a, v | bits);
}
